						public function __construct($aRow = null, $sClassAlias = '', $aAttToLoad = null, $aExtendedDataSpec = null) {
	parent::__construct($aRow, $sClassAlias, $aAttToLoad, $aExtendedDataSpec);

	$this->sLastError = '';
